public void keepAttachmentsOnDeath(PlayerEvent.Clone event) {
		if (event.isWasDeath()) {
			for (DeferredHolder<AttachmentType<?>, ? extends AttachmentType<?>> attachmentHolder : ATTACHMENTS_TO_PRESERVE_ON_DEATH) {
				copyAttachmentData(event.getOriginal(), event.getEntity(), attachmentHolder.get());
			}
		}
	}

private <T> void copyAttachmentData(Player source, Player target, AttachmentType<T> type) {
		if (source.hasData(type)) {
			target.setData(type, source.getData(type));
		}
	}

public TankComponentItemHandler(ItemStack upgrade) {
			super(upgrade, ModCoreDataComponents.LENIENT_CONTAINER.get(), 4);
			migrateLegacyContents();
		}

private void migrateLegacyContents() {
			ItemContainerContents currentContents = getContents();
			ItemStack inputStack = getStackFromContents(currentContents, INPUT_SLOT);
			if (!inputStack.isEmpty() && !hasValidFluidHandler(inputStack, false)) {
				setStackInSlot(INPUT_SLOT, ItemStack.EMPTY);
				setStackInSlot(INPUT_RESULT_SLOT, inputStack);
			}
			ItemStack outputStack = getStackFromContents(currentContents, OUTPUT_SLOT);
			if (!outputStack.isEmpty() && !hasValidFluidHandler(outputStack, true)) {
				setStackInSlot(OUTPUT_SLOT, ItemStack.EMPTY);
				setStackInSlot(OUTPUT_RESULT_SLOT, outputStack);
			}
		}

@Override
		protected void onContentsChanged(int slot, ItemStack oldStack, ItemStack newStack) {
			super.onContentsChanged(slot, oldStack, newStack);
			save();
		}

private boolean hasValidFluidHandler(ItemStack stack, boolean isOutput) {
			return getFluidHandler(stack).map(fluidHandler -> isValidFluidHandler(fluidHandler, isOutput)).orElse(false);
		}

public DefaultEmberItemCapability(@Nonnull ItemStack stack, double capacity) {
        this.stack = stack;
        if (!stack.hasTagCompound()) {
            stack.setTagCompound(new NBTTagCompound());
            setEmber(0);
            setEmberCapacity(capacity);
        } else {
            migrateLegacy();
        }
    }

@Override
    public double getEmber() {
        return stack.hasTagCompound() ? stack.getTagCompound().getDouble("ember") : 0;
    }

@Override
    public double getEmberCapacity() {
        return stack.hasTagCompound() ? stack.getTagCompound().getDouble("emberCapacity") : 0;
    }

@Override
    public void setEmber(double value) {
        if (stack.hasTagCompound()) {
            stack.getTagCompound().setDouble("ember", value);
        }
    }

@Override
    public void setEmberCapacity(double value) {
        if (stack.hasTagCompound()) {
            stack.getTagCompound().setDouble("emberCapacity", value);
        }
    }

public void migrateLegacy() {
        if (stack.hasTagCompound()) {
            NBTTagCompound compound = stack.getTagCompound();
            if (compound.hasKey(Embers.MODID + ":ember")) {
                compound.setDouble("ember", compound.getDouble(Embers.MODID + ":ember"));
                compound.removeTag(Embers.MODID + ":ember");
            }
            if (compound.hasKey(Embers.MODID + ":emberCapacity")) {
                compound.setDouble("emberCapacity", compound.getDouble(Embers.MODID + ":emberCapacity"));
                compound.removeTag(Embers.MODID + ":emberCapacity");
            }
        }
    }
